#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

inline int calculate(int kaidan) {
    return (kaidan / 10 / 365) + 1; // Inline function for calculation
}

int func(int kaidan) {
    if (kaidan == 0) return 1; // Base case
    if (kaidan == 1) return 1; // Base case
    if (kaidan == 2) return 2; // Base case

    int prev1 = 1, prev2 = 1, prev3 = 2; // Store last three results
    int current;

    for (int now = 3; now <= kaidan; ++now) {
        current = prev1 + prev2 + prev3; // Calculate current based on previous three
        prev1 = prev2; // Update for next iteration
        prev2 = prev3;
        prev3 = current;
    }

    return current; // Return the result for kaidan
}

int main() {
    int n, ans;
    while (cin >> n && n != 0) {
        ans = func(n);
        cout << calculate(ans) << endl; // Use inline function
    }
    return 0;
}

